CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE CHECK(email=lower(trim(email))), password_hash text NOT NULL, currency text NOT NULL DEFAULT 'MXN' CHECK(currency='MXN'), onboarded boolean NOT NULL DEFAULT false, monthly_income numeric(16,2) NOT NULL DEFAULT 0 CHECK(monthly_income>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL);
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,type text NOT NULL CHECK(type IN ('BANK','CASH','DEBIT','OTHER')),initial_balance numeric(16,2) NOT NULL DEFAULT 0,currency text NOT NULL CHECK(currency='MXN'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,user_id));
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,type text NOT NULL CHECK(type IN ('INCOME','EXPENSE')),classification text NOT NULL CHECK(classification IN ('NEED','WANT')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,user_id),UNIQUE(user_id,name,type));
CREATE TABLE savings_goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,target_amount numeric(16,2) NOT NULL CHECK(target_amount>0),target_date date,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,user_id));
CREATE TABLE transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),account_id uuid NOT NULL,category_id uuid,savings_goal_id uuid,type text NOT NULL CHECK(type IN ('INCOME','EXPENSE','SAVING')),amount numeric(16,2) NOT NULL CHECK(amount>0),description text NOT NULL DEFAULT '',transaction_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(account_id,user_id) REFERENCES accounts(id,user_id),FOREIGN KEY(category_id,user_id) REFERENCES categories(id,user_id),FOREIGN KEY(savings_goal_id,user_id) REFERENCES savings_goals(id,user_id),CHECK((type='SAVING' AND category_id IS NULL) OR (type<>'SAVING' AND category_id IS NOT NULL AND savings_goal_id IS NULL)));
CREATE TABLE budget_strategies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES users(id),name text NOT NULL);
CREATE TABLE budget_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),strategy_id uuid NOT NULL REFERENCES budget_strategies(id),bucket text NOT NULL CHECK(bucket IN ('needs','wants','savings')),percentage integer NOT NULL CHECK(percentage BETWEEN 0 AND 100),UNIQUE(strategy_id,bucket));
CREATE INDEX accounts_user_idx ON accounts(user_id);
CREATE INDEX categories_user_idx ON categories(user_id);
CREATE INDEX goals_user_idx ON savings_goals(user_id);
CREATE INDEX refresh_user_idx ON refresh_tokens(user_id);
CREATE INDEX transactions_history_idx ON transactions(user_id,transaction_date DESC,created_at DESC);
CREATE INDEX transactions_account_idx ON transactions(user_id,account_id);
CREATE INDEX transactions_category_idx ON transactions(user_id,category_id);
CREATE INDEX transactions_goal_idx ON transactions(user_id,savings_goal_id);
